/** void MultiplyInvertedPaletteRGBComponents(u16 i, u8 r, u8 g, u8 b) */
export function MultiplyInvertedPaletteRGBComponents(i: any, r: any, g: any, b: any): any {
  let curRed, curGreen, curBlue;
      let color: any = gPlttBufferUnfaded[i];

      curRed   = (color & RGB_RED);
      curGreen = (color & RGB_GREEN) >>  5;
      curBlue  = (color & RGB_BLUE)  >> 10;

      curRed   += (((0x1F - curRed)   * r) >> 4);
      curGreen += (((0x1F - curGreen) * g) >> 4);
      curBlue  += (((0x1F - curBlue)  * b) >> 4);

      color  = curRed;
      color |= (curGreen <<  5);
      color |= (curBlue  << 10);

      gPlttBufferFaded[i] = color;
}

/** void MultiplyPaletteRGBComponents(u16 i, u8 r, u8 g, u8 b) */
export function MultiplyPaletteRGBComponents(i: any, r: any, g: any, b: any): any {
  let curRed, curGreen, curBlue;
      let color: any = gPlttBufferUnfaded[i];

      curRed   = (color & RGB_RED);
      curGreen = (color & RGB_GREEN) >>  5;
      curBlue  = (color & RGB_BLUE)  >> 10;

      curRed   -= ((curRed   * r) >> 4);
      curGreen -= ((curGreen * g) >> 4);
      curBlue  -= ((curBlue  * b) >> 4);

      color  = curRed;
      color |= (curGreen <<  5);
      color |= (curBlue  << 10);

      gPlttBufferFaded[i] = color;
}

