export function RideUpEscalatorOut(task: any): any {
  let sprite: any = null;
      sprite =gSprites[gPlayerAvatar.spriteId];
      sprite.x2 = Cos(_0x84, task.data[2]);
      sprite.y2 = Sin(_0x94, task.data[2]);
      task.data[3]++;
      if (task.data[3] & 1)
      {
          task.data[2]++;
      }
}

