/** static bool8 EscalatorWarpIn_Down_Ride(struct Task *task) */
export function EscalatorWarpIn_Down_Ride(task: any): any {
  let sprite: any = null;
      sprite =gSprites[gPlayerAvatar.spriteId];
      sprite.x2 = Cos(_0x84, task.data[1]);
      sprite.y2 = Sin(_0x94, task.data[1]);
      task.data[2]++;
      if (task.data[2] & 1)
      {
          task.data[1]--;
      }
      if (task.data[1] == 0)
      {
          sprite.x2 = 0;
          sprite.y2 = 0;
          task.tState = 5;
      }
      return FALSE;
}

