/** static void TeleportWarpInFieldEffect_Init(struct Task *task) */
export function TeleportWarpInFieldEffect_Init(task: any): any {
  let sprite: any = null;
      let centerToCornerVecY: any = null;
      if (IsWeatherNotFadingIn())
      {
          sprite =gSprites[gPlayerAvatar.spriteId];
          centerToCornerVecY = -(sprite.centerToCornerVecY << 1);
          sprite.y2 = -(sprite.y + sprite.centerToCornerVecY + gSpriteCoordOffsetY + centerToCornerVecY);
          gObjectEvents[gPlayerAvatar.objectEventId].invisible = FALSE;
          task.data[0]++;
          task.data[1] = 8;
          task.data[2] = 1;
          task.data[14] = sprite.subspriteMode;
          task.data[15] = GetPlayerFacingDirection();
          PlaySE(SE_WARP_IN);
      }
}

/** static void TeleportWarpInFieldEffect_SpinEnter(struct Task *task) */
export function TeleportWarpInFieldEffect_SpinEnter(task: any): any {
  const spinDirections: any = [DIR_SOUTH, DIR_WEST, DIR_EAST, DIR_NORTH, DIR_SOUTH];
      let objectEvent: any =gObjectEvents[gPlayerAvatar.objectEventId];
      let sprite: any =gSprites[gPlayerAvatar.spriteId];
      if ((sprite.y2 += task.data[1]) >= -8)
      {
          if (task.data[13] == 0)
          {
              task.data[13]++;
              objectEvent.triggerGroundEffectsOnMove = TRUE;
              sprite.subspriteMode = task.data[14];
          }
      }
      else
      {
          sprite.oam.priority = 1;
          if (sprite.subspriteMode != SUBSPRITES_OFF)
          {
              sprite.subspriteMode = SUBSPRITES_IGNORE_PRIORITY;
          }
      }
      if (sprite.y2 >= -_0x30 && task.data[1] > 1 && !(sprite.y2 & 1))
      {
          task.data[1]--;
      }
      if ((--task.data[2]) == 0)
      {
          task.data[2] = 4;
          ObjectEventTurn(objectEvent, spinDirections[objectEvent.facingDirection]);
      }
      if (sprite.y2 >= 0)
      {
          sprite.y2 = 0;
          task.data[0]++;
          task.data[1] = 1;
          task.data[2] = 0;
      }
}

/** static void TeleportWarpInFieldEffect_SpinGround(struct Task *task) */
export function TeleportWarpInFieldEffect_SpinGround(task: any): any {
  const spinDirections: any = [DIR_SOUTH, DIR_WEST, DIR_EAST, DIR_NORTH, DIR_SOUTH];
      let objectEvent: any =gObjectEvents[gPlayerAvatar.objectEventId];
      if ((--task.data[1]) == 0)
      {
          ObjectEventTurn(objectEvent, spinDirections[objectEvent.facingDirection]);
          task.data[1] = 8;
          if ((++task.data[2]) > 4 && task.data[14] == objectEvent.facingDirection)
          {
              UnlockPlayerFieldControls();
              CameraObjectReset();
              UnfreezeObjectEvents();
              DestroyTask(FindTaskIdByFunc(Task_TeleportWarpIn));
          }
      }
}

