/** u8 FldEff_RayquazaSpotlight(void) */
export function FldEff_RayquazaSpotlight(): any {
  let i, j, k;
      let spriteId: any = CreateSprite(gFieldEffectObjectTemplatePointers[FLDEFFOBJ_RAYQUAZA], 120, -24, 1);
      let sprite: any =gSprites[spriteId];

      sprite.oam.priority = 1;
      sprite.oam.paletteNum = 4;
      sprite.data[0] = 0;
      sprite.data[1] = 0;
      sprite.data[2] = 0;
      sprite.data[3] = -1;
      sprite.data[4] = sprite.y;
      sprite.data[5] = 0;
      SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG0 | BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_BG2 | BLDCNT_TGT2_BG3 | BLDCNT_TGT2_OBJ | BLDCNT_TGT2_BD);
      SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(14, 14));
      SetGpuReg(REG_OFFSET_WININ, WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR | WININ_WIN1_BG_ALL | WININ_WIN1_OBJ | WININ_WIN1_CLR);
      LoadPalette(sSpotlight_Pal, BG_PLTT_ID(12), 0);
      SetGpuReg(REG_OFFSET_BG0VOFS, 120);
      for (i = 3; i < 15; i++)
      {
          for (j = 12; j < 18; j++)
          {
              ((BG_SCREEN_ADDR(31)))[i * 32 + j] = 0xBFF4 + i * 6 + j + 1;
          }
      }
      for (k = 0; k < 90; k++)
      {
          for (i = 0; i < 8; i++)
          {
              (BG_CHAR_ADDR(2) + (k + 1) * 32 + i * 4) = (sSpotlight_Gfx[k * 32 + i * 4 + 1] << 8) + sSpotlight_Gfx[k * 32 + i * 4];
              (BG_CHAR_ADDR(2) + (k + 1) * 32 + i * 4 + 2) = (sSpotlight_Gfx[k * 32 + i * 4 + 3] << 8) + sSpotlight_Gfx[k * 32 + i * 4 + 2];
          }
      }
      return spriteId;
}

