/** static void FlyInFieldEffect_BirdSwoopDown(struct Task *task) */
export function FlyInFieldEffect_BirdSwoopDown(task: any): any {
  let objectEvent: any = null;
      objectEvent =gObjectEvents[gPlayerAvatar.objectEventId];
      if (!ObjectEventIsMovementOverridden(objectEvent) || ObjectEventClearHeldMovementIfFinished(objectEvent))
      {
          task.tState++;
          task.tTimer = 17;
          task.tAvatarFlags = gPlayerAvatar.flags;
          gPlayerAvatar.preventStep = TRUE;
          SetPlayerAvatarStateMask(PLAYER_AVATAR_FLAG_ON_FOOT);
          if (task.tAvatarFlags & PLAYER_AVATAR_FLAG_SURFING)
          {
              SetSurfBlob_BobState(objectEvent.fieldEffectSpriteId, BOB_NONE);
          }
          ObjectEventSetGraphicsId(objectEvent, GetPlayerAvatarGraphicsIdByStateId(PLAYER_AVATAR_STATE_SURFING));
          CameraObjectFreeze();
          ObjectEventTurn(objectEvent, DIR_WEST);
          StartSpriteAnim(gSprites[objectEvent.spriteId], ANIM_GET_ON_OFF_POKEMON_WEST);
          objectEvent.invisible = FALSE;
          task.tBirdSpriteId = CreateFlyBirdSprite();
          StartFlyBirdSwoopDown(task.tBirdSpriteId);
          SetFlyBirdPlayerSpriteId(task.tBirdSpriteId, objectEvent.spriteId);
      }
}

/** static void FlyInFieldEffect_FlyInWithBird(struct Task *task) */
export function FlyInFieldEffect_FlyInWithBird(task: any): any {
  let objectEvent: any = null;
      let sprite: any = null;
      if (task.tTimer == 0 || (--task.tTimer) == 0)
      {
          objectEvent =gObjectEvents[gPlayerAvatar.objectEventId];
          sprite =gSprites[objectEvent.spriteId];
          SetFlyBirdPlayerSpriteId(task.tBirdSpriteId, MAX_SPRITES);
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          sprite.x2 = 0;
          sprite.y2 = 0;
          task.tState++;
          task.tTimer = 0;
      }
}

