/** static void Task_DeoxysRockCameraShake(u8 taskId) */
export function Task_DeoxysRockCameraShake(taskId: any): any {
  let data: any = gTasks[taskId].data;
      if (tEnding)
      {
          if (++tEndDelay > 20)
          {
              tEndDelay = 0;
              if (tShake != 0)
                  tShake--;
          }
      }
      else
      {
          tShake = 4;
      }

      if (++tShakeDelay > 1)
      {
          tShakeDelay = 0;

          if (++tShakeUp & 1)
              SetCameraPanning(0, -tShake);
          else
              SetCameraPanning(0, tShake);
      }
      UpdateCameraPanning();
      if (tShake == 0)
          DestroyTask(taskId);
}

