/** static void CreateDeoxysRockFragments(struct Sprite *sprite) */
export function CreateDeoxysRockFragments(sprite: any): any {
  let i: any = null;
      let xPos: any = gTotalCameraPixelOffsetX + sprite.x + sprite.x2;
      let yPos: any = gTotalCameraPixelOffsetY + sprite.y + sprite.y2 - 4;

      for (i = 0; i < 4; i++)
      {
          let spriteId: any = CreateSprite(sSpriteTemplate_DeoxysRockFragment, xPos, yPos, 0);
          if (spriteId != MAX_SPRITES)
          {
              StartSpriteAnim(gSprites[spriteId], i);
              gSprites[spriteId].data[0] = i;
              gSprites[spriteId].oam.paletteNum = sprite.oam.paletteNum;
          }
      }
}

/** static void SpriteCB_DeoxysRockFragment(struct Sprite *sprite) */
export function SpriteCB_DeoxysRockFragment(sprite: any): any {
  switch (sprite.data[0])
      {
      case 0:
          sprite.x -= 16;
          sprite.y -= 12;
          break;
      case 1:
          sprite.x += 16;
          sprite.y -= 12;
          break;
      case 2:
          sprite.x -= 16;
          sprite.y += 12;
          break;
      case 3:
          sprite.x += 16;
          sprite.y += 12;
          break;
      }
      if (sprite.x < -4 || sprite.x > DISPLAY_WIDTH + 4 || sprite.y < -4 || sprite.y > DISPLAY_HEIGHT + 4)
          DestroySprite(sprite);
}

/** bool8 FldEff_MoveDeoxysRock(struct Sprite *sprite) */
export function FldEff_MoveDeoxysRock(sprite: any): any {
  let objectEventId: any = null;
      if (!TryGetObjectEventIdByLocalIdAndMap(gFieldEffectArguments[0], gFieldEffectArguments[1], gFieldEffectArguments[2],objectEventId))
      {
          let object: any = null;
          let xPos, yPos;
          let taskId: any = null;
          object =gObjectEvents[objectEventId];
          xPos = object.currentCoords.x - MAP_OFFSET;
          yPos = object.currentCoords.y - MAP_OFFSET;
          xPos = (gFieldEffectArguments[3] - xPos) * 16;
          yPos = (gFieldEffectArguments[4] - yPos) * 16;
          ShiftObjectEventCoords(object, gFieldEffectArguments[3] + MAP_OFFSET, gFieldEffectArguments[4] + MAP_OFFSET);
          taskId = CreateTask(Task_MoveDeoxysRock, 80);
          gTasks[taskId].tSpriteId = object.spriteId;
          gTasks[taskId].tTargetX = gSprites[object.spriteId].x + xPos;
          gTasks[taskId].tTargetY = gSprites[object.spriteId].y + yPos;
          gTasks[taskId].tMoveSteps = gFieldEffectArguments[5];
          gTasks[taskId].tObjEventId = objectEventId;
      }
      return FALSE;
}

/** static void Task_MoveDeoxysRock(u8 taskId) */
export function Task_MoveDeoxysRock(taskId: any): any {
  let data: any = gTasks[taskId].data;
      let sprite: any =gSprites[tSpriteId];
      switch (tState)
      {
          case 0:
              tCurX = sprite.x << 4;
              tCurY = sprite.y << 4;
              tVelocityX = SAFE_DIV(tTargetX * 16 - tCurX, tMoveSteps);
              tVelocityY = SAFE_DIV(tTargetY * 16 - tCurY, tMoveSteps);
              tState++;
               
          case 1:
              if (tMoveSteps != 0)
              {
                  tMoveSteps--;
                  tCurX += tVelocityX;
                  tCurY += tVelocityY;
                  sprite.x = tCurX >> 4;
                  sprite.y = tCurY >> 4;
              }
              else
              {
                  let object: any =gObjectEvents[tObjEventId];
                  sprite.x = tTargetX;
                  sprite.y = tTargetY;
                  ShiftStillObjectEventCoords(object);
                  object.triggerGroundEffectsOnStop = TRUE;
                  FieldEffectActiveListRemove(FLDEFF_MOVE_DEOXYS_ROCK);
                  DestroyTask(taskId);
              }
              break;
      }
}

